prop is_on_segment(p, a, b cart(R, R)):
    a != b
    exist t R st {0 <= t, t <= 1, p(1) = (((1 - t) * a(1)) + (t * b(1))), p(2) = (((1 - t) * a(2)) + (t * b(2)))}

thm three_squares_on_strict_cut:
    ? forall a, b, c cart(R, R):
        $f11::is_on_segment(c, a, b)
        c != a
        c != b
        =>:
            exist ab_c, ab_d, cb_c, cb_d, ac_c, ac_d cart(R, R), first, second, opposite R+ st {$m0::f0::is_square(a, b, ab_c, ab_d), $f4::has_parallelogram_area(a, b, ab_c, ab_d, first), $m0::f0::is_square(c, b, cb_c, cb_d), $f4::has_parallelogram_area(c, b, cb_c, cb_d, second), $m0::f0::is_square(a, c, ac_c, ac_d), $f4::has_parallelogram_area(a, c, ac_c, ac_d, opposite)}
    by def $f11::is_on_segment(c, a, b)
    a != c
    release thm proposition_46(a, b)
    obtain ab_c, ab_d from exist u, v cart(R, R) st {$m0::f0::is_square(a, b, u, v), $f4::is_proper_parallelogram(a, b, u, v)}
    release thm proper_square_area_exists(a, b, ab_c, ab_d)
    obtain first from exist value R+ st {$f4::has_parallelogram_area(a, b, ab_c, ab_d, value)}
    release thm proposition_46(c, b)
    obtain cb_c, cb_d from exist u, v cart(R, R) st {$m0::f0::is_square(c, b, u, v), $f4::is_proper_parallelogram(c, b, u, v)}
    release thm proper_square_area_exists(c, b, cb_c, cb_d)
    obtain second from exist value R+ st {$f4::has_parallelogram_area(c, b, cb_c, cb_d, value)}
    release thm proposition_46(a, c)
    obtain ac_c, ac_d from exist u, v cart(R, R) st {$m0::f0::is_square(a, c, u, v), $f4::is_proper_parallelogram(a, c, u, v)}
    release thm proper_square_area_exists(a, c, ac_c, ac_d)
    obtain opposite from exist value R+ st {$f4::has_parallelogram_area(a, c, ac_c, ac_d, value)}
    witness exist out_ab_c, out_ab_d, out_cb_c, out_cb_d, out_ac_c, out_ac_d cart(R, R), out_first, out_second, out_opposite R+ st {$m0::f0::is_square(a, b, out_ab_c, out_ab_d), $f4::has_parallelogram_area(a, b, out_ab_c, out_ab_d, out_first), $m0::f0::is_square(c, b, out_cb_c, out_cb_d), $f4::has_parallelogram_area(c, b, out_cb_c, out_cb_d, out_second), $m0::f0::is_square(a, c, out_ac_c, out_ac_d), $f4::has_parallelogram_area(a, c, out_ac_c, out_ac_d, out_opposite)} from ab_c, ab_d, cb_c, cb_d, ac_c, ac_d, first, second, opposite

thm four_squares_on_midpoint_cut_edges:
    ? forall a, b, c, d cart(R, R):
        a != d
        d != b
        a != c
        c != d
        =>:
            exist ad_c, ad_d, db_c, db_d, ac_c, ac_d, cd_c, cd_d cart(R, R), first_area, second_area, half_area, offset_area R+ st {$m0::f0::is_square(a, d, ad_c, ad_d), $f4::has_parallelogram_area(a, d, ad_c, ad_d, first_area), $m0::f0::is_square(d, b, db_c, db_d), $f4::has_parallelogram_area(d, b, db_c, db_d, second_area), $m0::f0::is_square(a, c, ac_c, ac_d), $f4::has_parallelogram_area(a, c, ac_c, ac_d, half_area), $m0::f0::is_square(c, d, cd_c, cd_d), $f4::has_parallelogram_area(c, d, cd_c, cd_d, offset_area)}
    release thm proposition_46(a, d)
    obtain ad_c, ad_d from exist third, fourth cart(R, R) st {$m0::f0::is_square(a, d, third, fourth), $f4::is_proper_parallelogram(a, d, third, fourth)}
    release thm proper_square_area_exists(a, d, ad_c, ad_d)
    obtain first_area from exist value R+ st {$f4::has_parallelogram_area(a, d, ad_c, ad_d, value)}
    release thm proposition_46(d, b)
    obtain db_c, db_d from exist third, fourth cart(R, R) st {$m0::f0::is_square(d, b, third, fourth), $f4::is_proper_parallelogram(d, b, third, fourth)}
    release thm proper_square_area_exists(d, b, db_c, db_d)
    obtain second_area from exist value R+ st {$f4::has_parallelogram_area(d, b, db_c, db_d, value)}
    release thm proposition_46(a, c)
    obtain ac_c, ac_d from exist third, fourth cart(R, R) st {$m0::f0::is_square(a, c, third, fourth), $f4::is_proper_parallelogram(a, c, third, fourth)}
    release thm proper_square_area_exists(a, c, ac_c, ac_d)
    obtain half_area from exist value R+ st {$f4::has_parallelogram_area(a, c, ac_c, ac_d, value)}
    release thm proposition_46(c, d)
    obtain cd_c, cd_d from exist third, fourth cart(R, R) st {$m0::f0::is_square(c, d, third, fourth), $f4::is_proper_parallelogram(c, d, third, fourth)}
    release thm proper_square_area_exists(c, d, cd_c, cd_d)
    obtain offset_area from exist value R+ st {$f4::has_parallelogram_area(c, d, cd_c, cd_d, value)}
    witness exist out_ad_c, out_ad_d, out_db_c, out_db_d, out_ac_c, out_ac_d, out_cd_c, out_cd_d cart(R, R), out_first_area, out_second_area, out_half_area, out_offset_area R+ st {$m0::f0::is_square(a, d, out_ad_c, out_ad_d), $f4::has_parallelogram_area(a, d, out_ad_c, out_ad_d, out_first_area), $m0::f0::is_square(d, b, out_db_c, out_db_d), $f4::has_parallelogram_area(d, b, out_db_c, out_db_d, out_second_area), $m0::f0::is_square(a, c, out_ac_c, out_ac_d), $f4::has_parallelogram_area(a, c, out_ac_c, out_ac_d, out_half_area), $m0::f0::is_square(c, d, out_cd_c, out_cd_d), $f4::has_parallelogram_area(c, d, out_cd_c, out_cd_d, out_offset_area)} from ad_c, ad_d, db_c, db_d, ac_c, ac_d, cd_c, cd_d, first_area, second_area, half_area, offset_area

thm three_squares_on_triangle:
    ? forall a, b, c cart(R, R):
        $m0::f0::is_triangle(a, b, c)
        =>:
            exist ab_c, ab_d, bc_c, bc_d, ac_c, ac_d cart(R, R), first, second, opposite R+ st {$m0::f0::is_square(a, b, ab_c, ab_d), $f4::has_parallelogram_area(a, b, ab_c, ab_d, first), $m0::f0::is_square(b, c, bc_c, bc_d), $f4::has_parallelogram_area(b, c, bc_c, bc_d, second), $m0::f0::is_square(a, c, ac_c, ac_d), $f4::has_parallelogram_area(a, c, ac_c, ac_d, opposite)}
    release thm f1::triangle_vertices_distinct(a, b, c)
    release thm proposition_46(a, b)
    obtain ab_c, ab_d from exist u, v cart(R, R) st {$m0::f0::is_square(a, b, u, v), $f4::is_proper_parallelogram(a, b, u, v)}
    release thm proper_square_area_exists(a, b, ab_c, ab_d)
    obtain first from exist value R+ st {$f4::has_parallelogram_area(a, b, ab_c, ab_d, value)}
    release thm proposition_46(b, c)
    obtain bc_c, bc_d from exist u, v cart(R, R) st {$m0::f0::is_square(b, c, u, v), $f4::is_proper_parallelogram(b, c, u, v)}
    release thm proper_square_area_exists(b, c, bc_c, bc_d)
    obtain second from exist value R+ st {$f4::has_parallelogram_area(b, c, bc_c, bc_d, value)}
    release thm proposition_46(a, c)
    obtain ac_c, ac_d from exist u, v cart(R, R) st {$m0::f0::is_square(a, c, u, v), $f4::is_proper_parallelogram(a, c, u, v)}
    release thm proper_square_area_exists(a, c, ac_c, ac_d)
    obtain opposite from exist value R+ st {$f4::has_parallelogram_area(a, c, ac_c, ac_d, value)}
    witness exist out_ab_c, out_ab_d, out_bc_c, out_bc_d, out_ac_c, out_ac_d cart(R, R), out_first, out_second, out_opposite R+ st {$m0::f0::is_square(a, b, out_ab_c, out_ab_d), $f4::has_parallelogram_area(a, b, out_ab_c, out_ab_d, out_first), $m0::f0::is_square(b, c, out_bc_c, out_bc_d), $f4::has_parallelogram_area(b, c, out_bc_c, out_bc_d, out_second), $m0::f0::is_square(a, c, out_ac_c, out_ac_d), $f4::has_parallelogram_area(a, c, out_ac_c, out_ac_d, out_opposite)} from ab_c, ab_d, bc_c, bc_d, ac_c, ac_d, first, second, opposite
